// Pushes every var in .env.local up to Vercel as an encrypted Secret-type
// environment variable for the given environment (default: production).
// Each key is removed then re-added (Vercel's CLI has no clean "update"
// for existing vars) so re-running this is safe and idempotent.
//
// Run with: node scripts/sync-env-to-vercel.mjs [environment]
//   node scripts/sync-env-to-vercel.mjs production   (default)
//   node scripts/sync-env-to-vercel.mjs preview
//
// Skips comment lines, blank lines, and vars Vercel manages itself
// (VERCEL_OIDC_TOKEN is auto-generated by `vercel link`, not something to
// push manually).

import { readFileSync } from "fs";
import { execSync } from "child_process";

const environment = process.argv[2] || "production";
const SKIP_KEYS = new Set(["VERCEL_OIDC_TOKEN"]);

const raw = readFileSync(new URL("../.env.local", import.meta.url), "utf8");
const vars = [];
for (const line of raw.split("\n")) {
  const trimmed = line.trim();
  if (!trimmed || trimmed.startsWith("#")) continue;
  const m = trimmed.match(/^([A-Z0-9_]+)=(.*)$/);
  if (!m) continue;
  const [, key, rawValue] = m;
  if (SKIP_KEYS.has(key)) continue;
  const value = rawValue.replace(/^"|"$/g, "");
  if (!value) continue;
  vars.push({ key, value });
}

console.log(`Syncing ${vars.length} variables to Vercel (${environment})...\n`);

for (const { key, value } of vars) {
  try {
    execSync(`npx --yes vercel env rm ${key} ${environment} --yes`, { stdio: "pipe" });
  } catch {
    // fine — means it didn't exist yet
  }
  try {
    execSync(
      `npx --yes vercel env add ${key} ${environment} --sensitive --yes`,
      { input: value, stdio: ["pipe", "pipe", "pipe"] }
    );
    console.log(`✓ ${key}`);
  } catch (err) {
    console.error(`✗ ${key} — ${err.message}`);
  }
}

console.log("\nDone. Redeploy for changes to take effect: npx vercel deploy --prod");
